    family: family.id,
    roleId,
    title,
    subtitle,
    type: family.type,
    body,
    hint: `e17起應徵${ROLE_NAMES[roleId]}；目前rank恰為${RANKS[family.id]}，滿足該級任職條件後，從rank-exit選擇目前職級離場。`,
    symbol: SYMBOLS[family.id],
